-- ✅ Check of TASK 4 – generated by the teacher's build script, do not edit.
-- It compares a summary (md5) of your model signups_by_country with the expected one: PASS = your rows are right.
-- FAIL: the rows differ – compare rows_found with rows_expected and re-read the task.
-- ERROR: usually a column is missing or named differently – the columns must be: country, channel, signups.
with summary as (
    select count(*) as n, md5(coalesce(string_agg(concat_ws('|', country, channel, signups), E'\n' order by concat_ws('|', country, channel, signups) collate "C"), '')) as h from {{ ref('signups_by_country') }}
)
select n as rows_found, 6 as rows_expected
from summary
where h <> '070ca72cf6dcc14923d85110525c4c0d'
